using System.Linq.Expressions;
using InviteCraft.Domain.Common;
using Microsoft.EntityFrameworkCore;

namespace InviteCraft.Infrastructure.Persistence;

internal static class ModelBuilderConventions
{
    public const int EnumMaxLength = 32;

    /// <summary>
    /// Ids are UUID v7 generated by the application (decision D11), never by the database. Without this,
    /// EF treats a new child with a pre-set key (e.g. <c>template.Assets.Add(new TemplateAsset())</c>) as an
    /// existing row and issues an UPDATE instead of an INSERT.
    /// </summary>
    public static void UseClientGeneratedKeys(this ModelBuilder modelBuilder)
    {
        foreach (var entityType in modelBuilder.Model.GetEntityTypes())
        {
            var key = entityType.FindPrimaryKey();
            if (key is { Properties.Count: 1 } && key.Properties[0].ClrType == typeof(Guid))
                key.Properties[0].ValueGenerated = Microsoft.EntityFrameworkCore.Metadata.ValueGenerated.Never;
        }
    }

    /// <summary>Adds <c>WHERE NOT is_deleted</c> to every query on soft-deletable entities.</summary>
    public static void ApplySoftDeleteQueryFilters(this ModelBuilder modelBuilder)
    {
        var softDeletable = modelBuilder.Model.GetEntityTypes()
            .Where(t => t.BaseType is null && typeof(ISoftDeletable).IsAssignableFrom(t.ClrType))
            .ToList();

        foreach (var entityType in softDeletable)
        {
            var parameter = Expression.Parameter(entityType.ClrType, "e");
            var notDeleted = Expression.Not(Expression.Property(parameter, nameof(ISoftDeletable.IsDeleted)));
            modelBuilder.Entity(entityType.ClrType).HasQueryFilter(Expression.Lambda(notDeleted, parameter));
        }
    }

    /// <summary>
    /// Stores every enum as varchar(32) holding the member name (readable in SQL, safe to reorder)
    /// and adds a CHECK constraint so the database rejects unknown values.
    /// </summary>
    public static void ApplyEnumStringConventions(this ModelBuilder modelBuilder)
    {
        foreach (var entityType in modelBuilder.Model.GetEntityTypes())
        {
            var tableName = entityType.GetTableName();

            foreach (var property in entityType.GetProperties())
            {
                var enumType = Nullable.GetUnderlyingType(property.ClrType) ?? property.ClrType;
                if (!enumType.IsEnum)
                    continue;

                property.SetProviderClrType(typeof(string));
                property.SetMaxLength(EnumMaxLength);

                var column = property.GetColumnName();
                var allowed = string.Join(", ", Enum.GetNames(enumType).Select(n => $"'{n}'"));
                entityType.AddCheckConstraint($"ck_{tableName}_{column}", $"{column} IN ({allowed})");
            }
        }
    }
}
